function processItems(items) {
  items.forEach((item, index) => {
    // Add conditional breakpoint here:
    // Condition: index === 5
    // → Only pauses when processing the 6th item
    console.log(item.name);
  });
}

// Logpoint example:
// Message: "Processing item: {item.name} at index {index}"
// → Logs without pausing execution

// To debug DOM mutations:
// 1. Right-click element in Elements panel
// 2. Select "Break on" → "subtree modifications"
// 3. The debugger pauses when something changes this element

// To debug event listeners:
// 1. Go to Sources → Event Listener Breakpoints
// 2. Expand the event type (e.g., Mouse → click)
// 3. Check the box — debugger pauses on any click event

// Set a breakpoint inside a nested function
function outer() {
  let x = 1;
  function inner() {
    let y = 2;
    // ← Set breakpoint here
    debugger; // or use DevTools breakpoint
    console.log(x + y);
  }
  inner();
}

// In the debugger:
// Call Stack: inner → outer → (anonymous)
// Scope: { y: 1, x: 1 } (local + closure)
// Watch: add 'x + y' to monitor the expression
